class User:
    def __init__(self, username: str, email: str, password_hash: str, created_at: str = None):
        self.username = username
        self.email = email
        self.password_hash = password_hash
        self.created_at = created_at or datetime.utcnow().isoformat()
        self.stories_created: List[str] = []
        self.stories_contributed: List[str] = []

    def to_dict(self) -> Dict:
        return {
            "username": self.username,
            "email": self.email,
            "created_at": self.created_at,
            "stories_created": self.stories_created,
            "stories_contributed": self.stories_contributed
        }


class AuthManager:
    def __init__(self):
        self.users: Dict[str, User] = {}  # username -> User
        self.sessions: Dict[str, Tuple[str, float]] = {}  # token -> (username, expiry_time)
        self._lock = threading.Lock()

    def _hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def register(self, username: str, email: str, password: str) -> Optional[User]:
        with self._lock:
            if username in self.users:
                return None
            user = User(
                username=username,
                email=email,
                password_hash=self._hash_password(password)
            )
            self.users[username] = user
            return user

    def login(self, username: str, password: str) -> Optional[str]:
        with self._lock:
            user = self.users.get(username)
            if not user or user.password_hash != self._hash_password(password):
                return None
            token = secrets.token_urlsafe(32)
            expiry = time.time() + 86400  # 24 hours
            self.sessions[token] = (username, expiry)
            return token

    def logout(self, token: str) -> bool:
        with self._lock:
            if token in self.sessions:
                del self.sessions[token]
                return True
            return False

    def validate_token(self, token: str) -> Optional[str]:
        with self._lock:
            if token not in self.sessions:
                return None
            username, expiry = self.sessions[token]
            if time.time() > expiry:
                del self.sessions[token]
                return None
            return username

    def get_user(self, username: str) -> Optional[User]:
        return self.users.get(username)


