        self.title = title
        self.creator = creator
        self.created_at = created_at or datetime.utcnow().isoformat()
        self.last_updated = self.created_at
        self.chapters: List[Dict] = []  # [{"chapter_id": str, "title": str, "content": str, "author": str, "updated_at": str}]
        self.contributors: set = {creator}
        self.status: str = "draft"  # draft, published

    def add_chapter(self, chapter_id: str, title: str, content: str, author: str) -> bool:
        if any(c["chapter_id"] == chapter_id for c in self.chapters):
            return False
        self.chapters.append({
            "chapter_id": chapter_id,
            "title": title,
            "content": content,
            "author": author,
            "updated_at": datetime.utcnow().isoformat()
        })
        self.contributors.add(author)
        self.last_updated = datetime.utcnow().isoformat()
        return True

    def update_chapter(self, chapter_id: str, content: str, author: str) -> bool:
        for chapter in self.chapters:
            if chapter["chapter_id"] == chapter_id:
                chapter["content"] = content
                chapter["author"] = author
                chapter["updated_at"] = datetime.utcnow().isoformat()
                self.contributors.add(author)
                self.last_updated = datetime.utcnow().isoformat()
                return True
        return False

    def to_dict(self) -> Dict:
        return {
            "story_id": self.story_id,
            "title": self.title,
            "creator": self.creator,
            "created_at": self.created_at,
            "last_updated": self.last_updated,
            "chapters": self.chapters,
            "contributors": list(self.contributors),
            "status": self.status
        }


