        self.stories: Dict[str, Story] = {}
        self._lock = threading.Lock()
        self._edit_locks: Dict[str, threading.Lock] = defaultdict(threading.Lock)

    def create_story(self, story_id: str, title: str, creator: str) -> Optional[Story]:
        with self._lock:
            if story_id in self.stories:
                return None
            story = Story(story_id=story_id, title=title, creator=creator)
            self.stories[story_id] = story
            return story

