                author_id=user_id,
                chapters=[{"chapter_id": "ch1", "content": "", "last_edited_by": user_id, "last_edited_at": datetime.utcnow().isoformat()}]
            )
            storage.stories[story_id] = new_story
            storage.story_participants[story_id] = [user_id]

            return True, story_id, "Story created successfully"

    @staticmethod
    def add_chapter(user_id: str, story_id: str) -> Tuple[bool, str]:
        with storage.lock:
            if story_id not in storage.stories:
                return False, "Story not found"
            if user_id not in storage.story_participants[story_id]:
                return False, "You are not authorized to edit this story"

            story = storage.stories[story_id]
            chapter_num = len(story.chapters) + 1
            chapter_id = f"ch{chapter_num}"
            story.chapters.append({
                "chapter_id": chapter_id,
                "content": "",
                "last_edited_by": user_id,
                "last_edited_at": datetime.utcnow().isoformat()
            })
            story.last_updated_at = datetime.utcnow().isoformat()

            return True, "Chapter added successfully"

    @staticmethod
    def edit_chapter(user_id: str, story_id: str, chapter_id: str, content: str) -> Tuple[bool, str]:
        with storage.lock:
            if story_id not in storage.stories:
                return False, "Story not found"
            if user_id not in storage.story_participants[story_id]:
                return False, "You are not authorized to edit this story"

            story = storage.stories[story_id]
            for chapter in story.chapters:
                if chapter["chapter_id"] == chapter_id:
                    # Save version before edit
                    VersionService.save_version(
                        story_id=story_id,
                        chapter_id=chapter_id,
                        content=chapter["content"],
                        edited_by=user_id
                    )

                    chapter["content"] = content
                    chapter["last_edited_by"] = user_id
                    chapter["last_edited_at"] = datetime.utcnow().isoformat()
                    story.last_updated_at = datetime.utcnow().isoformat()

                    return True, "Chapter updated successfully"

            return False, "Chapter not found"

    @staticmethod
    def get_story(story_id: str) -> Optional[Story]:
        with storage.lock:
            return copy.deepcopy(storage.stories.get(story_id))

    @staticmethod
    def get_all_stories() -> List[Story]:
        with storage.lock:
            return [copy.deepcopy(story) for story in storage.stories.values()]


